/* prog21_date_validator.c
 * Reimplementation of the original binary's behaviour.
 * It validates a date given as the first command‑line argument.
 * The program prints "VALID" if the argument is a correct date in the
 * format YYYY‑MM‑DD, otherwise it prints "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return 1 if the given year is a leap year in the Gregorian calendar,
   0 otherwise. */
static int is_leap_year(int year)
{
    if (year % 4 != 0)          return 0;
    if (year % 100 != 0)        return 1;
    if (year % 400 == 0)        return 1;
    return 0;
}

/* Validate the date string.  Returns 1 for a valid date, 0 otherwise. */
static int validate_date(const char *s)
{
    /* Length must be exactly 10 characters: YYYY-MM-DD */
    if (strlen(s) != 10)
        return 0;

    /* Hyphens must be at the correct positions */
    if (s[4] != '-' || s[7] != '-')
        return 0;

    /* All other characters must be decimal digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!isdigit((unsigned char)s[i]))
            return 0;
    }

    /* Parse year, month and day */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Month must be 1..12 */
    if (month < 1 || month > 12)
        return 0;

    /* Days in each month (non‑leap year) */
    static const int days_in_month[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    int max_day = days_in_month[month - 1];
    if (month == 2 && is_leap_year(year))
        max_day = 29;

    /* Day must be within the allowed range */
    if (day < 1 || day > max_day)
        return 0;

    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
